#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LEN 64

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *pattern = argv[1];
    const char *text = argv[2];
    size_t plen = strlen(pattern);
    size_t tlen = strlen(text);
    if (plen > MAX_LEN || tlen > MAX_LEN) {
        puts("USAGE");
        return 0;
    }
    // dp[i][j] = pattern[0..i-1] matches text[0..j-1]
    bool dp[MAX_LEN + 1][MAX_LEN + 1];
    for (size_t i = 0; i <= plen; ++i) {
        for (size_t j = 0; j <= tlen; ++j) {
            dp[i][j] = false;
        }
    }
    dp[0][0] = true;
    // first column: pattern vs empty text
    for (size_t i = 1; i <= plen; ++i) {
        dp[i][0] = dp[i-1][0] && (pattern[i-1] == '*');
    }
    // fill table
    for (size_t i = 1; i <= plen; ++i) {
        for (size_t j = 1; j <= tlen; ++j) {
            char pc = pattern[i-1];
            char tc = text[j-1];
            if (pc == '*') {
                dp[i][j] = dp[i-1][j] || dp[i][j-1];
            } else if (pc == '?') {
                dp[i][j] = dp[i-1][j-1];
            } else {
                dp[i][j] = dp[i-1][j-1] && (pc == tc);
            }
        }
    }
    puts(dp[plen][tlen] ? "MATCH" : "NO_MATCH");
    return 0;
}
